'use strict';
const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const money = cents => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format((Number(cents)||0)/100);
const normalize = s => String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('pt-BR').trim();
const escapeHtml = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const MAX_QTY=99, MAX_LINES=40;
let catalog={settings:{storeName:'Repapelie',tagline:'Seu mundo de papel, criatividade e detalhes especiais.',intro:'',whatsapp:'',whatsappConfigured:false},categories:[],products:[]};
let requestLines=[], customerDetails={name:'',phone:'',deadline:'',notes:''}, currentCategory='all', detailProduct=null, editingLineKey=null, adminData=null, adminTab='overview', toastTimer, drawerReturnFocus=null;
const state={search:'',sort:'featured',availableOnly:false};
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3000)}
async function api(url,options={}){const opts={...options,headers:{...(options.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(options.headers||{})}};if(opts.body&&typeof opts.body!=='string'&&!(opts.body instanceof FormData))opts.body=JSON.stringify(opts.body);const r=await fetch(url,opts);let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.error||'Não foi possível concluir a operação.');return data}
function categoryName(id){return catalog.categories.find(c=>c.id===id)?.name||'Outros produtos'}
function priceLabel(p){if(p.priceMode==='fixed')return money(p.priceCents);if(p.priceMode==='starting')return `A partir de ${money(p.priceCents)}`;if(p.priceMode==='unavailable')return 'Indisponível';return 'Sob consulta'}
function productImage(p,cls='product-image'){const src=p.image||p.gallery?.[0];return src?`<img class="${cls}" src="${escapeHtml(src)}" alt="${escapeHtml(p.name)}" loading="lazy">`:`<div class="image-placeholder ${escapeHtml(cls)}" role="img" aria-label="Imagem de ${escapeHtml(p.name)}">✳</div>`}
function wireImageFallback(root=document){root.querySelectorAll('img').forEach(img=>{if(img.dataset.fallbackBound)return;img.dataset.fallbackBound='1';img.addEventListener('error',()=>{const fallback=document.createElement('div');fallback.className=`image-placeholder ${img.className}`;fallback.setAttribute('role','img');fallback.setAttribute('aria-label',img.alt||'Imagem indisponível');fallback.textContent='✳';img.replaceWith(fallback)},{once:true})})}
function persistRequest(){try{localStorage.setItem('repapelie-request-v1',JSON.stringify(requestLines.map(l=>({key:l.key,productId:l.productId,qty:l.qty,values:l.values,notes:l.notes}))))}catch{toast('Não foi possível guardar sua lista neste navegador.') } updateCount()}
function restoreRequest(){try{const raw=JSON.parse(localStorage.getItem('repapelie-request-v1')||'[]');if(!Array.isArray(raw))return;requestLines=raw.slice(0,MAX_LINES).map(l=>{const p=catalog.products.find(p=>p.id===l.productId);if(!p||p.availability==='unavailable')return null;const qty=Number(l.qty);if(!Number.isInteger(qty)||qty<1||qty>MAX_QTY)return null;const values={};for(const o of p.options||[]){const v=l.values?.[o.id];if(v==null)continue;const arr=Array.isArray(v)?v.filter(x=>o.choices.includes(x)):v;if(Array.isArray(arr)?arr.length:typeof arr==='string'?arr.length<=o.maxLength:o.choices.includes(arr))values[o.id]=arr;}return {key:String(l.key||crypto.randomUUID()),productId:p.id,qty,values,notes:String(l.notes||'').slice(0,500)}}).filter(Boolean);persistRequest()}catch{requestLines=[];persistRequest()}}
function updateCount(){$('#request-count').textContent=requestLines.reduce((s,l)=>s+l.qty,0);$('#drawer-count').textContent=`(${requestLines.reduce((s,l)=>s+l.qty,0)})`}
function visibleProducts(){let arr=catalog.products.filter(p=>currentCategory==='all'||p.categoryId===currentCategory);const q=normalize(state.search);if(q)arr=arr.filter(p=>normalize([p.name,p.shortDescription,p.description,categoryName(p.categoryId),p.sku,...(p.tags||[])].join(' ')).includes(q));if(state.availableOnly)arr=arr.filter(p=>p.availability==='available');if(state.sort==='name-asc')arr.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));if(state.sort==='name-desc')arr.sort((a,b)=>b.name.localeCompare(a.name,'pt-BR'));if(state.sort==='price-asc'||state.sort==='price-desc'){arr.sort((a,b)=>{const ap=['fixed','starting'].includes(a.priceMode)?a.priceCents:null,bp=['fixed','starting'].includes(b.priceMode)?b.priceCents:null;if(ap==null&&bp==null)return a.name.localeCompare(b.name,'pt-BR');if(ap==null)return 1;if(bp==null)return -1;return state.sort==='price-asc'?ap-bp:bp-ap})}return arr}
function renderCategories(){const categories=catalog.categories.filter(c=>catalog.products.some(p=>p.categoryId===c.id));$('#category-chips').innerHTML=[`<button class="chip ${currentCategory==='all'?'active':''}" data-category="all">Tudo</button>`,...categories.map(c=>`<button class="chip ${currentCategory===c.id?'active':''}" data-category="${escapeHtml(c.id)}">${escapeHtml(c.name)}</button>`)].join('');$('#category-chips').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{currentCategory=b.dataset.category;renderCategories();renderProducts()}))}
function renderProducts(){const products=visibleProducts();$('#product-grid').innerHTML=products.map((p,i)=>`<article class="product-card"><div class="product-image-wrap">${productImage(p)}${p.priceMode==='quote'?'<span class="product-badge">SOB CONSULTA</span>':p.availability==='made-to-order'?'<span class="product-badge">FEITO SOB ENCOMENDA</span>':''}<button class="quick-add" data-add="${escapeHtml(p.id)}" aria-label="Personalizar e adicionar ${escapeHtml(p.name)}">+</button></div><p class="product-category">${escapeHtml(categoryName(p.categoryId))}</p><h3 class="product-title">${escapeHtml(p.name)}</h3><p class="product-description">${escapeHtml(p.shortDescription||p.description||'Um produto especial da nossa seleção.')}</p><div class="product-bottom"><span class="product-price">${escapeHtml(priceLabel(p))}${p.priceMode==='starting'?'<small>valor inicial</small>':''}</span><button class="details-link" data-details="${escapeHtml(p.id)}">Ver detalhes ↗</button></div></article>`).join('');$('#result-count').textContent=`${products.length} ${products.length===1?'produto':'produtos'}`;$('#active-filter').textContent=currentCategory==='all'?'Todos os produtos':categoryName(currentCategory);$('#catalog-empty').hidden=products.length!==0;$('#product-grid').hidden=products.length===0;wireImageFallback($('#product-grid'));$('#product-grid').querySelectorAll('[data-add],[data-details]').forEach(b=>b.addEventListener('click',()=>openProduct(b.dataset.add||b.dataset.details)));}
function setCatalogText(){document.title=`${catalog.settings.storeName||'Repapelie'} — Papelaria com afeto`;$('#catalog-description').textContent=catalog.settings.tagline||'Encontre seus favoritos e monte sua lista de solicitação.';$('.wordmark:not(.admin-wordmark) > span:nth-child(2)').innerHTML=`${escapeHtml(catalog.settings.storeName||'Repapelie').toLowerCase()}<small>papelaria & afeto</small>`;$('#hero-intro').textContent=catalog.settings.intro||'Pequenos detalhes, grandes ideias. Explore o catálogo e conte pra gente o que você está imaginando.'}
async function loadCatalog(){try{catalog=await api('/api/public/catalog');setCatalogText();renderCategories();renderProducts();restoreRequest()}catch(e){$('#product-grid').innerHTML=`<div class="empty-state"><span class="empty-icon">✳</span><h3>Nosso catálogo está descansando.</h3><p>${escapeHtml(e.message)} Atualize a página daqui a pouco.</p></div>`;$('#product-grid').hidden=false;$('#catalog-empty').hidden=true}}
function optionField(o, value){const val=value??'';let control='';if(['select'].includes(o.type)){control=`<select name="${escapeHtml(o.id)}" ${o.required?'required':''}><option value="">Selecione…</option>${o.choices.map(c=>`<option ${val===c?'selected':''} value="${escapeHtml(c)}">${escapeHtml(c)}</option>`).join('')}</select>`}else if(['radio','color'].includes(o.type)){control=`<div class="choice-list">${o.choices.map((c,i)=>`<label class="choice-pill"><input type="radio" name="${escapeHtml(o.id)}" value="${escapeHtml(c)}" ${val===c?'checked':''} ${o.required?'required':''}><span>${escapeHtml(c)}</span></label>`).join('')}</div>`}else if(o.type==='checkbox'){const chosen=Array.isArray(val)?val:[];control=`<div class="choice-list">${o.choices.map(c=>`<label class="choice-pill"><input type="checkbox" name="${escapeHtml(o.id)}" value="${escapeHtml(c)}" ${chosen.includes(c)?'checked':''}><span>${escapeHtml(c)}</span></label>`).join('')}</div>`}else if(o.type==='textarea'){control=`<textarea name="${escapeHtml(o.id)}" maxlength="${o.maxLength}" placeholder="Escreva aqui…" ${o.required?'required':''}>${escapeHtml(val)}</textarea>`}else{control=`<input name="${escapeHtml(o.id)}" maxlength="${o.maxLength}" value="${escapeHtml(val)}" placeholder="Escreva aqui…" ${o.required?'required':''}>`}return `<fieldset class="option-field"><legend>${escapeHtml(o.label)} ${o.required?'<span aria-hidden="true">*</span>':''}${o.feeCents?` <span class="help">(+${money(o.feeCents)})</span>`:''}</legend>${o.help?`<p class="help">${escapeHtml(o.help)}</p>`:''}${control}</fieldset>`}
function openProduct(id,lineKey=null){const p=catalog.products.find(x=>x.id===id);if(!p)return toast('Este produto não está mais disponível no catálogo.');if(p.availability==='unavailable')return toast('Este produto está indisponível no momento.');detailProduct=p;editingLineKey=lineKey;const line=lineKey?requestLines.find(l=>l.key===lineKey):null;const modal=$('#modal-root');modal.innerHTML=`<div class="dialog-backdrop" data-backdrop><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="dialog-head"><div><p class="eyebrow">${escapeHtml(categoryName(p.categoryId))}</p><h2 id="detail-title">${escapeHtml(line?'Editar seleção':p.name)}</h2></div><button class="close-button" data-close-dialog aria-label="Fechar">×</button></header><form id="customize-form"><div class="dialog-body"><div class="product-detail-layout"><div>${productImage(p,'detail-image')}${(p.gallery||[]).length?`<div class="detail-gallery">${p.gallery.map((src,i)=>`<button type="button" class="detail-gallery-thumb" data-gallery-image="${escapeHtml(src)}" aria-label="Ver foto ${i+2}"><img src="${escapeHtml(src)}" alt="" loading="lazy"></button>`).join('')}</div>`:''}</div><div><span class="detail-category">${escapeHtml(categoryName(p.categoryId))}${p.sku?` · Ref. ${escapeHtml(p.sku)}`:''}</span><p class="detail-price">${escapeHtml(priceLabel(p))}</p><p class="detail-description">${escapeHtml(p.description||p.shortDescription||'Consulte a loja para mais detalhes.')}</p>${(p.options||[]).map(o=>optionField(o,line?.values?.[o.id])).join('')}<div class="field"><label for="custom-qty">Quantidade</label><input id="custom-qty" name="qty" type="number" min="1" max="${MAX_QTY}" step="1" value="${line?.qty||1}" required></div><div class="field"><label for="custom-notes">Observações deste item (opcional)</label><textarea id="custom-notes" name="notes" maxlength="500" placeholder="Cores, nome para personalizar, tema…">${escapeHtml(line?.notes||'')}</textarea><span class="help">Até 500 caracteres. A viabilidade será confirmada pela loja.</span></div></div></div></div><footer class="dialog-actions"><button type="button" class="button button-outline" data-close-dialog>Cancelar</button><button type="submit" class="button button-dark">${line?'Salvar alterações':'Adicionar à solicitação'} ↗</button></footer></form></section></div>`;
wireImageFallback(modal);const close=()=>{modal.innerHTML='';detailProduct=null;editingLineKey=null};modal.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',close));modal.querySelector('[data-backdrop]').addEventListener('click',e=>{if(e.target===e.currentTarget)close()});modal.querySelectorAll('[data-gallery-image]').forEach(b=>b.addEventListener('click',()=>{const old=modal.querySelector('.detail-image');const img=b.querySelector('img');const next=document.createElement('img');next.className='detail-image';next.src=b.dataset.galleryImage;next.alt=`${p.name} — foto adicional`;next.loading='lazy';old.replaceWith(next)}));modal.querySelector('#customize-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;const fd=new FormData(form);const qty=Number(fd.get('qty'));if(!Number.isSafeInteger(qty)||qty<1||qty>MAX_QTY){toast(`A quantidade deve ser um número inteiro entre 1 e ${MAX_QTY}.`);return}const values={};for(const o of p.options||[]){let v;if(o.type==='checkbox')v=fd.getAll(o.id);else v=fd.get(o.id);if(o.required&&(!v||(Array.isArray(v)&&!v.length))){toast(`Preencha a opção “${o.label}”.`);return}if(v!==null&&v!==''&&v!==undefined){if(Array.isArray(v)){if(v.some(x=>!o.choices.includes(x))){toast('Uma das opções não é válida.');return}}else if(['select','radio','color'].includes(o.type)&&!o.choices.includes(v)){toast('A opção selecionada não é válida.');return}else if(['text','textarea'].includes(o.type)&&String(v).length>o.maxLength){toast(`O campo “${o.label}” excedeu o limite.`);return}values[o.id]=v}}const line={key:lineKey||crypto.randomUUID(),productId:p.id,qty,values,notes:String(fd.get('notes')||'').trim().slice(0,500)};if(lineKey){const i=requestLines.findIndex(l=>l.key===lineKey);if(i>=0)requestLines[i]=line}else{if(requestLines.length>=MAX_LINES)return toast(`Sua lista pode ter até ${MAX_LINES} itens diferentes.`);requestLines.push(line)}persistRequest();close();toast(lineKey?'Seleção atualizada.':'Adicionado à sua solicitação.');if($('#request-drawer').hidden===false)renderDrawer()});modal.querySelector('[data-close-dialog]').focus()}
function linePricing(line){const p=catalog.products.find(x=>x.id===line.productId);if(!p)return {known:false,total:0,unit:null};let unit=['fixed','starting'].includes(p.priceMode)?p.priceCents: null;for(const o of p.options||[])if(o.feeCents){const v=line.values?.[o.id];if(v!=null&&v!==''&&(!Array.isArray(v)||v.length))unit=(unit??0)+o.feeCents}return {known:unit!==null&&p.priceMode!=='quote'&&p.priceMode!=='unavailable',total:unit===null?0:unit*line.qty,unit,mode:p.priceMode}}
function summary(){let known=0,unknown=0;requestLines.forEach(l=>{const p=catalog.products.find(p=>p.id===l.productId);if(!p)return;const v=linePricing(l);if(v.known)known+=v.total;else unknown+=l.qty});return {known,unknown}}
function selectedDescription(p,line){return (p.options||[]).map(o=>{const v=line.values?.[o.id];if(v==null||v===''||(Array.isArray(v)&&!v.length))return null;return `${o.label}: ${Array.isArray(v)?v.join(', '):v}`}).filter(Boolean).join(' · ')}
function renderDrawer(){const existingForm=$('#customer-form');if(existingForm){const fd=new FormData(existingForm);customerDetails={name:String(fd.get('name')||''),phone:String(fd.get('phone')||''),deadline:String(fd.get('deadline')||''),notes:String(fd.get('notes')||'')}}updateCount();const content=$('#drawer-content'),footer=$('#drawer-footer');if(!requestLines.length){content.innerHTML='<div class="drawer-empty"><span>✳</span><h3>Sua lista começa aqui.</h3><p>Explore o catálogo e adicione os produtos que despertam sua ideia.</p><button class="button button-dark" id="back-to-catalog">Explorar catálogo ↘</button></div>';footer.innerHTML='';$('#back-to-catalog').addEventListener('click',()=>{closeDrawer();$('#catalogo').scrollIntoView({behavior:'smooth'})});return}content.innerHTML=requestLines.map(l=>{const p=catalog.products.find(p=>p.id===l.productId);if(!p)return '';const price=linePricing(l);const desc=selectedDescription(p,l);return `<article class="request-line"><div>${productImage(p,'request-thumb')}</div><div><h3>${escapeHtml(p.name)}</h3><p class="line-meta">${escapeHtml(categoryName(p.categoryId))}${desc?`<br>${escapeHtml(desc)}`:''}${l.notes?`<br>Obs.: ${escapeHtml(l.notes)}`:''}</p><div class="qty-control"><button type="button" data-qty="${escapeHtml(l.key)}" data-delta="-1" aria-label="Diminuir quantidade">−</button><input aria-label="Quantidade de ${escapeHtml(p.name)}" type="number" min="1" max="${MAX_QTY}" step="1" value="${l.qty}" data-qty-input="${escapeHtml(l.key)}"><button type="button" data-qty="${escapeHtml(l.key)}" data-delta="1" aria-label="Aumentar quantidade">+</button></div><button class="remove-line" data-remove="${escapeHtml(l.key)}">Remover · Editar opções</button><button class="text-action" data-edit-line="${escapeHtml(l.key)}">Editar personalização</button></div><div class="line-price">${price.known?money(price.total):'Sob consulta'}</div></article>`}).join('')+`<form id="customer-form" class="request-form"><h3>Vamos nos conhecer?</h3><p>Esses dados são opcionais e ajudam a loja a entender sua solicitação.</p><div class="field"><label for="customer-name">Seu nome (opcional)</label><input id="customer-name" name="name" maxlength="100" value="${escapeHtml(customerDetails.name)}" placeholder="Como podemos te chamar?"></div><div class="field"><label for="customer-phone">Seu WhatsApp (opcional)</label><input id="customer-phone" name="phone" type="tel" maxlength="25" value="${escapeHtml(customerDetails.phone)}" placeholder="(11) 99999-9999"></div><div class="field"><label for="customer-deadline">Data desejada (opcional)</label><input id="customer-deadline" name="deadline" type="date" value="${escapeHtml(customerDetails.deadline)}"></div><div class="field"><label for="customer-notes">Observações gerais (opcional)</label><textarea id="customer-notes" name="notes" maxlength="1000" placeholder="Conte um pouco sobre sua ideia…">${escapeHtml(customerDetails.notes)}</textarea></div></form>`;wireImageFallback(content);
const sums=summary();footer.innerHTML=`<div class="total-row"><span>Subtotal estimado dos itens com preço definido</span><strong>${money(sums.known)}</strong></div>${sums.unknown?`<div class="total-row"><span>Unidades sob consulta</span><strong>${sums.unknown}</strong></div>`:''}<p class="estimate-note">${sums.unknown?'Parte dos itens não tem preço definido. ':''}Valores são estimativas, não representam uma compra. A disponibilidade, personalizações, preço final e prazo serão confirmados pela Repapelie.</p><label class="privacy-check"><input id="privacy-ack" type="checkbox"><span>Entendi que esta é uma solicitação, não uma compra, e que as informações serão incluídas na mensagem para o WhatsApp da loja.</span></label><button id="prepare-whatsapp" class="button button-dark button-full">Revisar solicitação e abrir WhatsApp ↗</button><button id="clear-request" class="text-action" style="margin-top:10px">Limpar minha lista</button>`;
content.querySelectorAll('[data-qty]').forEach(b=>b.addEventListener('click',()=>changeQty(b.dataset.qty,Number(b.dataset.delta))));content.querySelectorAll('[data-qty-input]').forEach(i=>i.addEventListener('change',()=>{const q=Number(i.value);if(!Number.isSafeInteger(q)||q<1||q>MAX_QTY){toast(`Use uma quantidade inteira entre 1 e ${MAX_QTY}.`);i.value=requestLines.find(l=>l.key===i.dataset.qtyInput)?.qty||1;return}const l=requestLines.find(l=>l.key===i.dataset.qtyInput);if(l)l.qty=q;persistRequest();renderDrawer()}));content.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{requestLines=requestLines.filter(l=>l.key!==b.dataset.remove);persistRequest();renderDrawer();toast('Item removido da lista.')}));content.querySelectorAll('[data-edit-line]').forEach(b=>b.addEventListener('click',()=>openProduct(requestLines.find(l=>l.key===b.dataset.editLine)?.productId,b.dataset.editLine)));$('#customer-form').addEventListener('input',e=>{const fd=new FormData(e.currentTarget);customerDetails={name:String(fd.get('name')||''),phone:String(fd.get('phone')||''),deadline:String(fd.get('deadline')||''),notes:String(fd.get('notes')||'')}});$('#prepare-whatsapp').addEventListener('click',prepareWhatsApp);$('#clear-request').addEventListener('click',()=>{if(confirm('Quer mesmo limpar todos os itens da sua solicitação?')){requestLines=[];persistRequest();renderDrawer();toast('Sua lista foi limpa.')}})}
function changeQty(key,delta){const l=requestLines.find(x=>x.key===key);if(!l)return;const n=l.qty+delta;if(n<1||n>MAX_QTY){toast(`A quantidade deve ficar entre 1 e ${MAX_QTY}.`);return}l.qty=n;persistRequest();renderDrawer()}
function openDrawer(){drawerReturnFocus=document.activeElement;$('#request-drawer').hidden=false;document.body.style.overflow='hidden';renderDrawer();$('.close-button',$('#request-drawer')).focus()}
function closeDrawer(){ $('#request-drawer').hidden=true;document.body.style.overflow='';if(drawerReturnFocus?.focus)drawerReturnFocus.focus()}
function validateLineForMessage(line,p){if(!Number.isSafeInteger(line.qty)||line.qty<1||line.qty>MAX_QTY)throw Error(`A quantidade de “${p.name}” é inválida.`);for(const o of p.options||[]){const v=line.values?.[o.id];if(o.required&&(v==null||v===''||(Array.isArray(v)&&!v.length)))throw Error(`Escolha a opção obrigatória “${o.label}” para ${p.name}.`);if(v==null||v==='')continue;if(Array.isArray(v)){if(o.type!=='checkbox'||v.some(x=>!o.choices.includes(x)))throw Error(`Uma opção de “${p.name}” não é válida. Reabra o produto e revise.`)}else if(['select','radio','color'].includes(o.type)&&!o.choices.includes(v))throw Error(`A opção “${o.label}” de ${p.name} não é válida.`);else if(['text','textarea'].includes(o.type)&&String(v).length>o.maxLength)throw Error(`O texto de “${o.label}” excedeu o limite.`)}}
function buildMessage(form){const name=String(form.get('name')||'').trim().slice(0,100)||'Não informado';const phone=String(form.get('phone')||'').trim().slice(0,25)||'Não informado';const deadline=String(form.get('deadline')||'').trim();const notes=String(form.get('notes')||'').trim().slice(0,1000)||'Nenhuma';let fixedTotal=0,quoteCount=0;const lines=['Olá, Repapelie! Gostaria de fazer uma solicitação pelo catálogo.','','*MEUS DADOS*',`Nome: ${name}`,`Contato: ${phone}`,deadline?`Data desejada: ${deadline.split('-').reverse().join('/')}`:'Data desejada: Não informada','','*PRODUTOS SOLICITADOS*'];requestLines.forEach((l,i)=>{const p=catalog.products.find(p=>p.id===l.productId);if(!p)throw Error('Um produto da sua lista não está mais disponível. Atualize o catálogo e revise a solicitação.');if(!p.id||p.availability==='unavailable')throw Error(`O produto “${p.name}” está indisponível.`);validateLineForMessage(l,p);const price=linePricing(l);if(price.known)fixedTotal+=price.total;else quoteCount+=l.qty;const desc=selectedDescription(p,l)||'Não informado';lines.push('',`${i+1}. ${p.name}`,`   Referência: ${p.sku||'Não informado'}`,`   Quantidade: ${l.qty}`,`   Modelos e opções: ${desc}`,`   Personalização/observações: ${l.notes||'Não informado'}`,`   Preço unitário: ${price.known?money(price.unit):'Sob consulta'}`,`   Subtotal estimado: ${price.known?money(price.total):'Sob consulta'}`)});lines.push('','*RESUMO*',`Subtotal estimado dos itens com preço definido: ${money(fixedTotal)}`,`Unidades sob consulta: ${quoteCount}`,`Estimativa parcial: ${quoteCount?'A confirmar':money(fixedTotal)}`,`Observações gerais: ${notes}`,'','Entendo que esta é uma solicitação de disponibilidade e orçamento, e que os valores finais, a viabilidade das personalizações e demais condições serão confirmados pela Repapelie.','', 'Poderiam, por favor, verificar a disponibilidade e me orientar sobre os próximos passos?','','Obrigado(a)!');return lines.join('\n')}
function prepareWhatsApp(){if(!requestLines.length)return toast('Adicione ao menos um produto antes de continuar.');if(!$('#privacy-ack').checked)return toast('Confirme que entendeu como sua solicitação será encaminhada.');if(!catalog.settings.whatsappConfigured||!/^55\d{10,11}$/.test(catalog.settings.whatsapp||'')){toast('O WhatsApp da loja ainda não foi configurado. Entre em contato com a loja por outro canal.');return}let message;try{message=buildMessage(new FormData($('#customer-form')))}catch(e){toast(e.message);return}const url=`https://wa.me/${catalog.settings.whatsapp}?text=${encodeURIComponent(message)}`;if(!url.startsWith('https://wa.me/'))return toast('Não foi possível preparar o link do WhatsApp.');if(url.length>7000){showLongMessage(message);return}const modal=$('#modal-root');modal.innerHTML=`<div class="dialog-backdrop" data-backdrop><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="review-title"><header class="dialog-head"><div><p class="eyebrow">ÚLTIMA CONFERÊNCIA</p><h2 id="review-title">Revise sua solicitação</h2></div><button class="close-button" data-close-dialog aria-label="Fechar">×</button></header><div class="dialog-body"><div class="notice">Confira os itens e as personalizações antes de continuar. O WhatsApp será aberto para você revisar e enviar a mensagem manualmente. A loja ainda precisará confirmar disponibilidade, preço final e prazo.</div><div class="review-lines">${requestLines.map(l=>{const p=catalog.products.find(p=>p.id===l.productId);return `<div class="total-row"><span><b>${l.qty}× ${escapeHtml(p.name)}</b><br>${escapeHtml(selectedDescription(p,l)||'Sem opções específicas')}</span><strong>${linePricing(l).known?money(linePricing(l).total):'Sob consulta'}</strong></div>`}).join('')}</div><div class="field"><label for="message-preview">Mensagem que será preparada</label><textarea id="message-preview" rows="10" readonly>${escapeHtml(message)}</textarea></div><p class="estimate-note">Esta aplicação não consegue confirmar se a mensagem foi enviada. Depois de abrir o WhatsApp, confira e toque em enviar por lá.</p></div><footer class="dialog-actions"><button class="button button-outline" data-close-dialog>Voltar e editar</button><button id="open-wa-confirm" class="button button-dark">Abrir WhatsApp ↗</button></footer></section></div>`;const close=()=>modal.innerHTML='';modal.querySelectorAll('[data-close-dialog]').forEach(b=>b.addEventListener('click',close));modal.querySelector('[data-backdrop]').addEventListener('click',e=>{if(e.target===e.currentTarget)close()});$('#open-wa-confirm').addEventListener('click',()=>{const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.referrerPolicy='no-referrer';document.body.appendChild(link);link.click();link.remove();close();closeDrawer();toast('Link preparado. No WhatsApp, confira e envie a mensagem manualmente.');});$('#open-wa-confirm').focus()}
function showLongMessage(message){const parts=[];const max=2500;const lines=message.split('\n');let part='';for(const line of lines){if((part+'\n'+line).length>max&&part){parts.push(part);part='';}part+=(part?'\n':'')+line;}if(part)parts.push(part);const modal=$('#modal-root');modal.innerHTML=`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="long-title"><header class="dialog-head"><div><p class="eyebrow">MENSAGEM LONGA</p><h2 id="long-title">Vamos dividir em partes</h2></div><button class="close-button" data-close-dialog aria-label="Fechar">×</button></header><div class="dialog-body"><div class="notice warning">Sua solicitação é extensa. Para evitar que algum item seja cortado, copie e envie cada parte manualmente no WhatsApp, na ordem indicada.</div>${parts.map((p,i)=>`<div class="field"><label for="part-${i}">Parte ${i+1} de ${parts.length}</label><textarea id="part-${i}" rows="5" readonly>${escapeHtml(p)}</textarea><button class="button button-outline" data-copy-part="${i}">Copiar parte ${i+1}</button></div>`).join('')}<button class="button button-dark" id="long-open-wa">Abrir WhatsApp ↗</button></div></section></div>`;modal.querySelector('[data-close-dialog]').addEventListener('click',()=>modal.innerHTML='');modal.querySelectorAll('[data-copy-part]').forEach(b=>b.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(parts[Number(b.dataset.copyPart)]);toast('Parte copiada.')}catch{const t=$(`#part-${b.dataset.copyPart}`);t.select();toast('Selecione e copie o texto.')}}));$('#long-open-wa').addEventListener('click',()=>{const link=document.createElement('a');link.href=`https://wa.me/${catalog.settings.whatsapp}`;link.target='_blank';link.rel='noopener noreferrer';document.body.appendChild(link);link.click();link.remove();toast('Cole as partes copiadas no WhatsApp, na ordem.');});}
function showPublic(){ $('#admin-view').hidden=true;$('#public-view').hidden=false;$('.site-header').hidden=false;$('.announcement').hidden=false;$('.site-footer').hidden=false;history.replaceState(null,'','/');}
function showAdmin(){ $('#public-view').hidden=true;$('.site-header').hidden=true;$('.announcement').hidden=true;$('.site-footer').hidden=true;$('#admin-view').hidden=false;history.replaceState(null,'','#admin');checkAdmin()}
async function checkAdmin(){try{const status=await api('/api/admin/status');if(status.authenticated){adminData=await api('/api/admin/data');renderAdmin()}else renderAdminLogin(status.setupRequired)}catch(e){$('#admin-content').innerHTML=`<div class="admin-message error">${escapeHtml(e.message)}</div>`}}
function renderAdminLogin(setupRequired){$('#admin-view').classList.add('login-mode');$('#admin-content').innerHTML=`<div class="admin-login-wrap"><section class="admin-login"><a class="wordmark" href="/"><span class="mark">r.</span><span>repapelie<small>painel da loja</small></span></a><h1>${setupRequired?'Configure o acesso da loja':'Que bom ter você de volta.'}</h1><p>${setupRequired?'Crie o primeiro acesso administrativo com o token de configuração definido no ambiente do servidor.':'Entre para organizar seus produtos, personalizações e catálogo.'}</p><div id="login-message"></div><form id="admin-login-form">${setupRequired?'<div class="field"><label for="setup-token">Token de configuração inicial</label><input id="setup-token" name="setupToken" type="password" autocomplete="off" required><span class="help">O token é configurado no servidor e não deve ser compartilhado.</span></div>':''}<div class="field"><label for="admin-username">Usuário</label><input id="admin-username" name="username" autocomplete="username" minlength="3" maxlength="50" required></div><div class="field"><label for="admin-password">Senha</label><input id="admin-password" name="password" type="password" autocomplete="${setupRequired?'new-password':'current-password'}" minlength="12" maxlength="200" required></div>${setupRequired?'<p class="settings-note">Use uma senha exclusiva com pelo menos 12 caracteres. Não existe senha padrão. O token inicial precisa ser configurado antes de iniciar o servidor.</p>':''}<button class="button button-dark">${setupRequired?'Criar acesso seguro':'Entrar no painel'} ↗</button></form><button class="text-action" id="back-public" style="margin-top:17px">← Voltar ao catálogo</button></section></div>`;$('#admin-login-form').addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));const msg=$('#login-message');try{if(setupRequired)await api('/api/admin/setup',{method:'POST',body:b});else await api('/api/admin/login',{method:'POST',body:b});adminData=await api('/api/admin/data');toast(setupRequired?'Acesso administrativo criado.':'Acesso autorizado.');renderAdmin()}catch(err){msg.innerHTML=`<div class="admin-message error">${escapeHtml(err.message)}</div>`}});$('#back-public').addEventListener('click',showPublic)}
function adminHeading(title){$('#admin-page-title').textContent=title;$('#admin-breadcrumb-current').textContent=title.toLocaleUpperCase('pt-BR');$$('[data-admin-tab]').forEach(b=>b.classList.toggle('selected',b.dataset.adminTab===adminTab))}
async function renderAdmin(){if(!adminData){renderAdminLogin(true);return}$('#admin-view').classList.remove('login-mode');const titles={overview:'Visão geral',products:'Produtos',categories:'Categorias',settings:'Configurações da loja'};adminHeading(titles[adminTab]||'Visão geral');if(adminTab==='overview'){let o;try{o=await api('/api/admin/overview')}catch(e){return $('#admin-content').innerHTML=`<div class="admin-message error">${escapeHtml(e.message)}</div>`}$('#admin-content').innerHTML=`<div class="admin-welcome"><div><h2>Olá! Vamos cuidar do seu catálogo.</h2><p>Organize os produtos e deixe tudo pronto para compartilhar com seus clientes.</p></div><button class="button button-dark" id="add-first-product">+ Adicionar produto</button></div><div class="stats-grid"><article class="stat-card"><span>Produtos publicados</span><strong>${o.active}</strong><small>Visíveis no catálogo</small></article><article class="stat-card"><span>Produtos em rascunho/inativos</span><strong>${o.inactive}</strong><small>Não aparecem ao público</small></article><article class="stat-card"><span>Categorias</span><strong>${o.categories}</strong><small>Organização do catálogo</small></article><article class="stat-card"><span>Precisam de atenção</span><strong>${o.priceReview+o.missingImages}</strong><small>${o.priceReview} sem preço fixo · ${o.missingImages} sem foto</small></article></div><section class="admin-panel"><div class="panel-head"><div><h3>Atalhos</h3><p>As tarefas mais comuns, em um só lugar.</p></div></div><div class="panel-body quick-actions"><button class="quick-action" id="quick-add-product"><b>＋ Adicionar produto</b><span>Cadastre um item, fotos, preço e opções de personalização.</span></button><button class="quick-action" id="quick-categories"><b>▧ Organizar categorias</b><span>Crie e mantenha as prateleiras do catálogo organizadas.</span></button><button class="quick-action" id="quick-settings"><b>⚙ Configurar a loja</b><span>Atualize o WhatsApp e a apresentação pública.</span></button></div></section><section class="admin-panel"><div class="panel-head"><div><h3>Produtos recentes</h3><p>Últimos itens atualizados no catálogo.</p></div><button class="text-action" id="all-products">Ver todos ↗</button></div>${adminProductTable(adminData.products.slice().sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,5))}</section><section class="admin-panel"><div class="panel-head"><div><h3>Compartilhe sua loja</h3><p>Depois de publicar o site, copie o link para enviar pelo WhatsApp ou redes sociais.</p></div></div><div class="panel-body"><button class="button button-outline" id="copy-link-panel">Copiar link da loja ↗</button><p class="estimate-note">Endereço atual: <b id="current-public-url"></b>. Em produção, configure o domínio HTTPS da sua loja.</p></div></section>`;$('#add-first-product').onclick=()=>productEditor();$('#quick-add-product').onclick=()=>productEditor();$('#quick-categories').onclick=()=>switchTab('categories');$('#quick-settings').onclick=()=>switchTab('settings');$('#all-products').onclick=()=>switchTab('products');$('#copy-link-panel').onclick=copyStoreLink;$('#current-public-url').textContent=location.origin;wireProductTable();return}if(adminTab==='products'){const products=adminData.products||[];$('#admin-content').innerHTML=`<div class="admin-welcome"><div><h2>Seu catálogo, organizado.</h2><p>Edite preços, imagens, opções e o que fica visível para os clientes.</p></div><button class="button button-dark" id="new-product">+ Adicionar produto</button></div><section class="admin-panel"><div class="panel-head"><div><h3>Todos os produtos (${products.length})</h3><p>Produtos publicados aparecem no catálogo público.</p></div><input id="admin-product-search" placeholder="Buscar produto…" aria-label="Buscar produto" style="max-width:200px;border:1px solid #dfe4db;padding:9px;font-size:11px"></div><div id="admin-products-table">${adminProductTable(products)}</div></section>`;$('#new-product').onclick=()=>productEditor();$('#admin-product-search').addEventListener('input',e=>{const q=normalize(e.target.value);$('#admin-products-table').innerHTML=adminProductTable(products.filter(p=>normalize(`${p.name} ${p.sku} ${categoryName(p.categoryId)}`).includes(q)));wireProductTable()});wireProductTable();return}if(adminTab==='categories'){renderCategoriesAdmin();return}if(adminTab==='settings'){renderSettingsAdmin();return}}
function adminProductTable(products){if(!products.length)return `<div class="admin-empty"><span>✳</span><h3>Sua primeira prateleira está esperando.</h3><p>Adicione um produto para começar a montar o catálogo.</p><button class="button button-dark" id="empty-add-product">Adicionar primeiro produto</button></div>`;return `<div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>PRODUTO</th><th>CATEGORIA</th><th>PREÇO</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody>${products.map(p=>`<tr><td><div class="admin-product-cell">${p.image?`<img class="admin-thumb" src="${escapeHtml(p.image)}" alt="" loading="lazy">`:'<div class="admin-thumb"></div>'}<div><b>${escapeHtml(p.name)}</b><small>${escapeHtml(p.sku||'Sem referência')}</small></div></div></td><td>${escapeHtml(categoryName(p.categoryId))}</td><td>${escapeHtml(priceLabel(p))}</td><td><span class="status-tag ${p.active&&p.published?'':'off'}">${p.active&&p.published?'Publicado':'Rascunho/inativo'}</span></td><td><div class="table-actions"><button class="text-action" data-edit-product="${escapeHtml(p.id)}">Editar</button><button class="text-action" data-duplicate-product="${escapeHtml(p.id)}">Duplicar</button><button class="text-action danger" data-archive-product="${escapeHtml(p.id)}">${p.active?'Arquivar':'Reativar'}</button></div></td></tr>`).join('')}</tbody></table></div>`}
function wireProductTable(){const empty=$('#empty-add-product');if(empty)empty.onclick=()=>productEditor();$$('[data-edit-product]').forEach(b=>b.onclick=()=>productEditor(b.dataset.editProduct));$$('[data-duplicate-product]').forEach(b=>b.onclick=()=>{const p=adminData.products.find(p=>p.id===b.dataset.duplicateProduct);productEditor(null,p)});$$('[data-archive-product]').forEach(b=>b.onclick=async()=>{const p=adminData.products.find(p=>p.id===b.dataset.archiveProduct);if(!p)return;if(p.active&&!confirm(`Arquivar “${p.name}”? Ele deixará de aparecer no catálogo público.`))return;try{if(p.active)await api(`/api/admin/products/${p.id}`,{method:'DELETE'});else{await api(`/api/admin/products/${p.id}`,{method:'PUT',body:{...p,active:true,published:false}})}await refreshAdminData();renderAdmin();toast(p.active?'Produto arquivado.':'Produto reativado como rascunho.')}catch(e){toast(e.message)}})}
function productEditor(id=null,duplicate=null){const p=id?adminData.products.find(x=>x.id===id):duplicate;const isDuplicate=Boolean(duplicate);const base=p?JSON.parse(JSON.stringify(p)):{name:'',sku:'',categoryId:adminData.categories.find(c=>c.active)?.id||'',shortDescription:'',description:'',image:'',gallery:[],priceMode:'quote',priceCents:null,availability:'available',options:[],tags:[],active:true,published:false};if(isDuplicate){base.name+= ' (cópia)';base.sku='';base.published=false}const modal=$('#modal-root');modal.innerHTML=`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="product-editor-title" style="width:min(820px,100%)"><header class="dialog-head"><div><p class="eyebrow">PAINEL DA LOJA</p><h2 id="product-editor-title">${id?'Editar produto':isDuplicate?'Duplicar produto':'Adicionar produto'}</h2></div><button class="close-button" data-close-dialog aria-label="Fechar">×</button></header><form id="product-editor-form"><div class="dialog-body"><div id="product-editor-message"></div><div class="admin-form"><h3 class="form-section-title">Informações principais</h3><div class="field"><label for="p-name">Nome do produto *</label><input id="p-name" name="name" maxlength="100" value="${escapeHtml(base.name)}" required></div><div class="field"><label for="p-sku">Referência (opcional)</label><input id="p-sku" name="sku" maxlength="40" value="${escapeHtml(base.sku||'')}"></div><div class="field"><label for="p-category">Categoria *</label><select id="p-category" name="categoryId" required>${adminData.categories.filter(c=>c.active).map(c=>`<option value="${escapeHtml(c.id)}" ${base.categoryId===c.id?'selected':''}>${escapeHtml(c.name)}</option>`).join('')}</select></div><div class="field"><label for="p-availability">Disponibilidade</label><select id="p-availability" name="availability"><option value="available" ${base.availability==='available'?'selected':''}>Disponível</option><option value="made-to-order" ${base.availability==='made-to-order'?'selected':''}>Feito sob encomenda</option><option value="unavailable" ${base.availability==='unavailable'?'selected':''}>Temporariamente indisponível</option></select></div><div class="field span-2"><label for="p-short">Descrição curta</label><input id="p-short" name="shortDescription" maxlength="180" value="${escapeHtml(base.shortDescription||'')}" placeholder="Uma frase para apresentar o produto"></div><div class="field span-2"><label for="p-description">Descrição completa</label><textarea id="p-description" name="description" maxlength="2000" rows="3">${escapeHtml(base.description||'')}</textarea></div><h3 class="form-section-title">Fotos do produto</h3><div class="field span-2"><label for="p-image-file">Enviar foto de capa (JPEG, PNG ou WebP, até 4 MB)</label><input id="p-image-file" type="file" accept="image/jpeg,image/png,image/webp"><span class="help">A imagem é enviada ao servidor. A primeira foto será a capa do produto.</span><div class="upload-preview" id="cover-preview">${base.image?`<img src="${escapeHtml(base.image)}" alt="Prévia da capa"><span class="upload-hint">Foto atual</span>`:''}</div><input type="hidden" name="image" id="p-image" value="${escapeHtml(base.image||'')}"></div><div class="field span-2"><label for="p-gallery-files">Adicionar fotos à galeria (pode selecionar várias)</label><input id="p-gallery-files" type="file" accept="image/jpeg,image/png,image/webp" multiple><span class="help">Até 4 MB por foto. Use as setas para mudar a ordem e remova fotos que não quiser.</span><div id="gallery-manager" class="upload-preview" style="flex-wrap:wrap;align-items:flex-start">${(base.gallery||[]).map((src,i)=>galleryItemHtml(src,i)).join('')}</div><input type="hidden" name="gallery" id="p-gallery" value="${escapeHtml((base.gallery||[]).join(','))}"></div><h3 class="form-section-title">Preço e publicação</h3><div class="field"><label for="p-price-mode">Como mostrar o preço *</label><select id="p-price-mode" name="priceMode"><option value="fixed" ${base.priceMode==='fixed'?'selected':''}>Preço fixo</option><option value="starting" ${base.priceMode==='starting'?'selected':''}>A partir de</option><option value="quote" ${base.priceMode==='quote'?'selected':''}>Sob consulta</option><option value="unavailable" ${base.priceMode==='unavailable'?'selected':''}>Preço indisponível</option></select></div><div class="field" id="price-field"><label for="p-price">Preço em reais</label><input id="p-price" name="price" type="number" min="0" max="1000000" step="0.01" value="${base.priceCents==null?'':(base.priceCents/100).toFixed(2)}"><span class="help">O preço será tratado em centavos para evitar erros de arredondamento.</span></div><div class="field"><label for="p-tags">Etiquetas (separadas por vírgula)</label><input id="p-tags" name="tags" value="${escapeHtml((base.tags||[]).join(', '))}" maxlength="400"></div><div class="field"><span>Visibilidade</span><label class="check-row"><input type="checkbox" name="active" ${base.active?'checked':''}> Produto ativo</label><label class="check-row"><input type="checkbox" name="published" ${base.published?'checked':''}> Publicar no catálogo</label></div><h3 class="form-section-title">Modelos e personalizações</h3><div class="span-2"><p class="settings-note">Configure apenas as opções relevantes para este produto. As escolhas publicadas aparecerão para o cliente e serão incluídas na mensagem de solicitação.</p><div id="option-editor-list">${(base.options||[]).map((o,i)=>optionEditorHtml(o,i)).join('')}</div><button type="button" id="add-option" class="button button-outline">+ Adicionar opção de personalização</button></div></div></div><footer class="dialog-actions"><button type="button" class="button button-outline" data-close-dialog>Cancelar</button><button type="submit" class="button button-dark">Salvar ${base.published?'produto':'rascunho'} ↗</button></footer></form></section></div>`;
const close=()=>modal.innerHTML='';modal.querySelectorAll('[data-close-dialog]').forEach(b=>b.onclick=close);$('#p-price-mode').addEventListener('change',()=>{$('#price-field').classList.toggle('hidden',!['fixed','starting'].includes($('#p-price-mode').value))});$('#p-price-mode').dispatchEvent(new Event('change'));$('#add-option').onclick=()=>{const list=$('#option-editor-list');list.insertAdjacentHTML('beforeend',optionEditorHtml({id:`opt-${crypto.randomUUID()}`,label:'',type:'select',choices:[],required:false,help:'',maxLength:120,feeCents:0},list.children.length));wireOptionEditors()};wireOptionEditors();wireGalleryManager();$('#p-gallery-files').addEventListener('change',async e=>{const files=[...(e.target.files||[])];for(const file of files){if(file.size>4*1024*1024){toast(`${file.name}: a imagem deve ter até 4 MB.`);continue}try{const result=await fetch('/api/admin/upload',{method:'POST',headers:{'Content-Type':file.type},body:file});const data=await result.json();if(!result.ok)throw Error(data.error||'Falha no envio.');const list=$('#gallery-manager');list.insertAdjacentHTML('beforeend',galleryItemHtml(data.path,list.children.length));wireGalleryManager();syncGallery();toast('Foto adicionada à galeria.')}catch(err){toast(err.message)}}e.target.value='';});$('#p-image-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>4*1024*1024){toast('A imagem deve ter até 4 MB.');e.target.value='';return}const preview=$('#cover-preview');preview.textContent='Enviando imagem…';try{const result=await fetch('/api/admin/upload',{method:'POST',headers:{'Content-Type':file.type},body:file});const data=await result.json();if(!result.ok)throw Error(data.error||'Falha no envio.');$('#p-image').value=data.path;preview.innerHTML=`<img src="${escapeHtml(data.path)}" alt="Prévia da capa"><span class="upload-hint">Imagem enviada. Salve o produto para publicar.</span>`;toast('Foto enviada com sucesso.')}catch(err){preview.textContent='';toast(err.message)} });$('#product-editor-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const priceMode=f.get('priceMode');let priceCents=null;if(['fixed','starting'].includes(priceMode)){const price=Number(f.get('price'));if(!Number.isFinite(price)||price<0||price>1000000){toast('Informe um preço válido.');return}priceCents=Math.round(price*100)}const options=$$('.option-editor',$('#option-editor-list')).map(el=>{const g=n=>$( `[data-opt-field="${n}"]`,el);return {id:el.dataset.optionId,label:g('label').value,type:g('type').value,choices:g('choices').value.split('\n').map(s=>s.trim()).filter(Boolean),required:g('required').checked,help:g('help').value,maxLength:Number(g('maxLength').value)||120,feeCents:Math.round(Math.max(0,Number(g('fee').value)||0)*100)}});const payload={name:f.get('name'),sku:f.get('sku'),categoryId:f.get('categoryId'),shortDescription:f.get('shortDescription'),description:f.get('description'),image:f.get('image'),gallery:$$('#gallery-manager [data-gallery-src]').map(el=>el.dataset.gallerySrc),priceMode,priceCents,availability:f.get('availability'),options,tags:String(f.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),active:f.has('active'),published:f.has('published')};try{if(id)await api(`/api/admin/products/${id}`,{method:'PUT',body:payload});else await api('/api/admin/products',{method:'POST',body:payload});await refreshAdminData();close();adminTab='products';renderAdmin();toast(id?'Produto atualizado.':'Produto salvo.');}catch(err){$('#product-editor-message').innerHTML=`<div class="admin-message error">${escapeHtml(err.message)}</div>`}});$('#p-name').focus()}
function galleryItemHtml(src,i){return `<div data-gallery-src="${escapeHtml(src)}" style="width:105px;border:1px solid #e4e9df;padding:6px;background:#fff"><img src="${escapeHtml(src)}" alt="Foto adicional ${i+1}" style="width:100%;height:90px;object-fit:cover;background:#f0ece3"><div style="display:flex;justify-content:space-between;gap:3px;margin-top:5px"><button type="button" data-gallery-up aria-label="Mover foto para cima" class="text-action">↑</button><button type="button" data-gallery-down aria-label="Mover foto para baixo" class="text-action">↓</button><button type="button" data-gallery-remove class="text-action danger">×</button></div><small style="font-size:8px;color:#777">Foto ${i+1}</small></div>`}
function syncGallery(){const paths=$$('#gallery-manager [data-gallery-src]').map(el=>el.dataset.gallerySrc);$('#p-gallery').value=paths.join(',')}
function wireGalleryManager(){$$('#gallery-manager [data-gallery-up]').forEach(b=>b.onclick=()=>{const el=b.closest('[data-gallery-src]'),prev=el.previousElementSibling;if(prev){el.parentNode.insertBefore(el,prev);wireGalleryManager();syncGallery()}});$$('#gallery-manager [data-gallery-down]').forEach(b=>b.onclick=()=>{const el=b.closest('[data-gallery-src]'),next=el.nextElementSibling;if(next){el.parentNode.insertBefore(next,el);wireGalleryManager();syncGallery()}});$$('#gallery-manager [data-gallery-remove]').forEach(b=>b.onclick=()=>{b.closest('[data-gallery-src]').remove();wireGalleryManager();syncGallery()});syncGallery()}
function optionEditorHtml(o,i){return `<fieldset class="option-editor" data-option-id="${escapeHtml(o.id||`opt-${i}`)}"><button type="button" class="remove-option">Remover opção ×</button><div class="option-editor-grid"><div class="field"><label>Nome da opção *</label><input data-opt-field="label" maxlength="60" value="${escapeHtml(o.label||'')}" placeholder="Ex.: Tema, tamanho, cor" required></div><div class="field"><label>Tipo de resposta</label><select data-opt-field="type">${[['select','Lista suspensa'],['radio','Escolha única'],['checkbox','Múltipla escolha'],['text','Texto curto'],['textarea','Texto longo'],['color','Cores']].map(([v,l])=>`<option value="${v}" ${o.type===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field span-2"><label>Opções disponíveis (uma por linha)</label><textarea data-opt-field="choices" rows="3" placeholder="Ex.: Floral\nMinimalista\nInfantil">${escapeHtml((o.choices||[]).join('\n'))}</textarea><span class="help">Obrigatório para lista, escolha única, múltipla escolha e cores.</span></div><div class="field"><label>Taxa adicional por unidade (R$)</label><input data-opt-field="fee" type="number" min="0" max="100000" step="0.01" value="${((o.feeCents||0)/100).toFixed(2)}"></div><div class="field"><label>Limite de caracteres (campos de texto)</label><input data-opt-field="maxLength" type="number" min="1" max="500" value="${o.maxLength||120}"></div><div class="field span-2"><label>Texto de ajuda (opcional)</label><input data-opt-field="help" maxlength="160" value="${escapeHtml(o.help||'')}"></div><label class="check-row span-2"><input data-opt-field="required" type="checkbox" ${o.required?'checked':''}> Esta opção é obrigatória para o cliente</label></div></fieldset>`}
function wireOptionEditors(){ $$('.option-editor').forEach(el=>{const type=$('[data-opt-field="type"]',el),choices=$('[data-opt-field="choices"]',el);const update=()=>choices.closest('.field').classList.toggle('hidden',['text','textarea'].includes(type.value));type.onchange=update;update();$('.remove-option',el).onclick=()=>el.remove()})}
function renderCategoriesAdmin(){const cats=adminData.categories||[];$('#admin-content').innerHTML=`<div class="admin-welcome"><div><h2>Prateleiras organizadas.</h2><p>As categorias ajudam os clientes a encontrar o que procuram.</p></div></div><section class="admin-panel"><div class="panel-head"><div><h3>Adicionar categoria</h3><p>Use nomes simples e fáceis de entender.</p></div></div><div class="panel-body"><form id="category-form" style="display:flex;gap:10px;max-width:600px"><input name="name" maxlength="60" required placeholder="Ex.: Papelaria e escritório" style="flex:1;min-width:0;border:1px solid #dfe4db;padding:11px;font-size:12px"><button class="button button-dark">Criar categoria +</button></form></div></section><section class="admin-panel"><div class="panel-head"><h3>Categorias existentes (${cats.length})</h3></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>NOME</th><th>PRODUTOS</th><th>ORDEM</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody>${cats.slice().sort((a,b)=>a.order-b.order).map(c=>`<tr><td><b>${escapeHtml(c.name)}</b></td><td>${adminData.products.filter(p=>p.categoryId===c.id).length}</td><td><input data-cat-order="${escapeHtml(c.id)}" type="number" min="0" max="1000" value="${c.order}" style="width:60px;padding:5px;border:1px solid #dfe4db"></td><td><span class="status-tag ${c.active?'':'off'}">${c.active?'Ativa':'Inativa'}</span></td><td><div class="table-actions"><button class="text-action" data-cat-edit="${escapeHtml(c.id)}">Renomear</button><button class="text-action" data-cat-toggle="${escapeHtml(c.id)}">${c.active?'Desativar':'Ativar'}</button><button class="text-action danger" data-cat-delete="${escapeHtml(c.id)}">Excluir</button></div></td></tr>`).join('')}</tbody></table></div></section>`;$('#category-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/categories',{method:'POST',body:{name:new FormData(e.currentTarget).get('name')}});await refreshAdminData();renderCategoriesAdmin();toast('Categoria criada.')}catch(err){toast(err.message)}};$$('[data-cat-edit]').forEach(b=>b.onclick=async()=>{const c=cats.find(c=>c.id===b.dataset.catEdit);const name=prompt('Novo nome da categoria:',c.name);if(name===null)return;try{await api(`/api/admin/categories/${c.id}`,{method:'PUT',body:{name,active:c.active,order:Number($(`[data-cat-order="${c.id}"]`).value)}});await refreshAdminData();renderCategoriesAdmin();toast('Categoria atualizada.')}catch(e){toast(e.message)}});$$('[data-cat-toggle]').forEach(b=>b.onclick=async()=>{const c=cats.find(c=>c.id===b.dataset.catToggle);try{await api(`/api/admin/categories/${c.id}`,{method:'PUT',body:{name:c.name,active:!c.active,order:Number($(`[data-cat-order="${c.id}"]`).value)}});await refreshAdminData();renderCategoriesAdmin();toast('Status da categoria atualizado.')}catch(e){toast(e.message)}});$$('[data-cat-delete]').forEach(b=>b.onclick=async()=>{const c=cats.find(c=>c.id===b.dataset.catDelete);if(!confirm(`Excluir a categoria “${c.name}”?`))return;try{await api(`/api/admin/categories/${c.id}`,{method:'DELETE'});await refreshAdminData();renderCategoriesAdmin();toast('Categoria excluída.')}catch(e){toast(e.message)}});$$('[data-cat-order]').forEach(i=>i.onchange=async()=>{const c=cats.find(c=>c.id===i.dataset.catOrder);try{await api(`/api/admin/categories/${c.id}`,{method:'PUT',body:{name:c.name,active:c.active,order:Number(i.value)}});await refreshAdminData();toast('Ordem atualizada.')}catch(e){toast(e.message)}})}
function renderSettingsAdmin(){const s=adminData.settings;$('#admin-content').innerHTML=`<div class="admin-welcome"><div><h2>Deixe a loja com a sua cara.</h2><p>Essas informações aparecem no catálogo público e na experiência do cliente.</p></div></div><section class="admin-panel"><div class="panel-head"><div><h3>Apresentação da loja</h3><p>Preencha somente informações reais e confirmadas.</p></div></div><div class="panel-body"><form id="settings-form" class="admin-form"><div class="field"><label for="s-name">Nome da loja *</label><input id="s-name" name="storeName" maxlength="80" value="${escapeHtml(s.storeName)}" required></div><div class="field"><label for="s-whatsapp">WhatsApp da loja</label><input id="s-whatsapp" name="whatsapp" type="tel" maxlength="20" value="${escapeHtml(s.whatsapp||'')}" placeholder="5511999999999"><span class="help">Código do Brasil (55) + DDD + telefone, apenas números.</span></div><div class="field span-2"><label for="s-tagline">Frase principal</label><input id="s-tagline" name="tagline" maxlength="180" value="${escapeHtml(s.tagline||'')}"></div><div class="field span-2"><label for="s-intro">Texto de apresentação</label><textarea id="s-intro" name="intro" maxlength="500" rows="3">${escapeHtml(s.intro||'')}</textarea></div><div class="field span-2"><label for="s-pickup">Informações de retirada/entrega (opcional)</label><textarea id="s-pickup" name="pickupInfo" maxlength="300" rows="2">${escapeHtml(s.pickupInfo||'')}</textarea><span class="help">Não prometa prazos ou condições que a loja ainda não confirmou.</span></div><div class="field span-2"><label for="s-privacy">Contato para dúvidas de privacidade (opcional)</label><input id="s-privacy" name="privacyContact" maxlength="120" value="${escapeHtml(s.privacyContact||'')}"></div><div class="field span-2"><label class="check-row"><input name="catalogVisible" type="checkbox" ${s.catalogVisible?'checked':''}> Catálogo público visível</label></div><div class="span-2 settings-note">O WhatsApp será usado para preparar uma mensagem com os itens escolhidos. A pessoa cliente precisa conferir e enviar a mensagem manualmente. O navegador não informa se a mensagem foi enviada.</div><div class="span-2 form-actions"><button type="submit" class="button button-dark">Salvar configurações ↗</button></div></form></div></section><section class="admin-panel"><div class="panel-head"><h3>Privacidade e armazenamento</h3></div><div class="panel-body"><p class="settings-note">Os produtos, categorias e configurações ficam no arquivo de dados do servidor. As imagens ficam na pasta de uploads. Faça cópias de segurança regulares e confirme que o ambiente de hospedagem mantém os arquivos após reinicializações. Esta aplicação não salva solicitações dos clientes no servidor.</p><a href="/privacy.html" target="_blank" rel="noopener" class="text-action">Abrir aviso de privacidade ↗</a></div></section>`;$('#settings-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/admin/settings',{method:'PUT',body:{storeName:f.get('storeName'),whatsapp:f.get('whatsapp'),tagline:f.get('tagline'),intro:f.get('intro'),pickupInfo:f.get('pickupInfo'),privacyContact:f.get('privacyContact'),catalogVisible:f.has('catalogVisible')}});await refreshAdminData();await loadCatalog();renderSettingsAdmin();toast('Configurações salvas.')}catch(err){toast(err.message)}}}
async function refreshAdminData(){adminData=await api('/api/admin/data')}
function switchTab(tab){adminTab=tab;renderAdmin()}
async function copyStoreLink(){try{await navigator.clipboard.writeText(location.origin);toast('Link copiado. Publique o site e use o endereço HTTPS de produção para compartilhar.')}catch{prompt('Copie o link do catálogo:',location.origin)}}
function wireAdmin(){ $('#open-admin').onclick=showAdmin;$('#footer-admin').onclick=showAdmin;$$('[data-admin-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.adminTab));$('#admin-logout').onclick=async()=>{try{await api('/api/admin/logout',{method:'POST',body:{}})}catch{}adminData=null;adminTab='overview';showPublic();toast('Você saiu da área administrativa.')};$('#copy-store-link').onclick=copyStoreLink;}
function init(){ $('#year').textContent=new Date().getFullYear();wireAdmin();loadCatalog();$('#search').addEventListener('input',e=>{state.search=e.target.value;$('#clear-search').hidden=!state.search;renderProducts()});$('#clear-search').onclick=()=>{$('#search').value='';state.search='';$('#clear-search').hidden=true;renderProducts();$('#search').focus()};$('#sort').onchange=e=>{state.sort=e.target.value;renderProducts()};$('#available-only').onchange=e=>{state.availableOnly=e.target.checked;renderProducts()};$('.search-jump').onclick=()=>{$('#search').focus();$('#catalogo').scrollIntoView({behavior:'smooth'})};$('#open-request').onclick=openDrawer;$('#hero-request').onclick=openDrawer;$('#closing-request').onclick=openDrawer;$$('[data-close-drawer]').forEach(b=>b.onclick=closeDrawer);$('#request-drawer').addEventListener('click',e=>{if(e.target===$('#request-drawer'))closeDrawer()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal-root').innerHTML)$('#modal-root').innerHTML='';if(!$('#request-drawer').hidden)closeDrawer()}});if(location.hash==='#admin')showAdmin();}
init();
